        "tags": [
          "Slis"
        ],
        "description": "Lists all SLI resources under a parent resource.",
        "parameters": [
          {
            "$ref": "#/parameters/ServiceGroupBaseParameters"
          },
          {
            "$ref": "../../../../../../common-types/resource-management/v5/types.json#/parameters/ApiVersionParameter"
          }
        ],
        "responses": {
          "200": {
            "description": "Azure operation completed successfully.",
            "schema": {
              "$ref": "#/definitions/SliListResult"
            }
          },
          "default": {
            "description": "An unexpected error response.",
            "schema": {
              "$ref": "../../../../../../common-types/resource-management/v5/types.json#/definitions/ErrorResponse"
            }
          }
        },
        "x-ms-examples": {
          "SlisListByParent": {
            "$ref": "./examples/Slis_ListByParent.json"
          }
        },
        "x-ms-pageable": {
          "nextLinkName": "nextLink"
        }
      }
    },
    "/providers/Microsoft.Management/serviceGroups/{serviceGroupName}/providers/Microsoft.Monitor/slis/{sliName}": {
      "get": {
        "operationId": "Slis_Get",
        "tags": [
          "Slis"
        ],
        "description": "Gets an SLI resource.",
        "parameters": [
          {
            "$ref": "#/parameters/ServiceGroupBaseParameters"
          },
          {
            "$ref": "../../../../../../common-types/resource-management/v5/types.json#/parameters/ApiVersionParameter"
          },
          {
            "name": "sliName",
            "in": "path",
            "description": "Name of the SLI that is given by the user.",
            "required": true,
            "type": "string",
            "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_()~-]{2,63}$"
          }
        ],
        "responses": {
          "200": {
            "description": "Azure operation completed successfully.",
            "schema": {
              "$ref": "#/definitions/Sli"
            }
          },
          "default": {
            "description": "An unexpected error response.",
