          }
        },
        "x-ms-examples": {
          "GetSli": {
            "$ref": "./examples/Slis_Get.json"
          }
        }
      },
      "put": {
        "operationId": "Slis_CreateOrUpdate",
        "tags": [
          "Slis"
        ],
        "description": "Creates or updates an SLI resource.",
        "parameters": [
          {
            "$ref": "#/parameters/ServiceGroupBaseParameters"
          },
          {
            "$ref": "../../../../../../common-types/resource-management/v5/types.json#/parameters/ApiVersionParameter"
          },
          {
            "name": "sliName",
            "in": "path",
            "description": "Name of the SLI that is given by the user.",
            "required": true,
            "type": "string",
            "pattern": "^[a-zA-Z0-9][a-zA-Z0-9_()~-]{2,63}$"
          },
          {
            "name": "resource",
            "in": "body",
            "description": "Resource create parameters.",
            "required": true,
            "schema": {
              "$ref": "#/definitions/Sli"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Resource 'Sli' update operation succeeded",
            "schema": {
              "$ref": "#/definitions/Sli"
            }
          },
          "201": {
            "description": "Resource 'Sli' create operation succeeded",
            "schema": {
              "$ref": "#/definitions/Sli"
            }
          },
          "default": {
            "description": "An unexpected error response.",
            "schema": {
              "$ref": "../../../../../../common-types/resource-management/v5/types.json#/definitions/ErrorResponse"
            }
          }
        },
        "x-ms-examples": {
          "CreateSli": {
            "$ref": "./examples/Slis_CreateOrUpdate.json"
          }
        }
      },
      "delete": {
        "operationId": "Slis_Delete",
        "tags": [
          "Slis"
        ],
        "description": "Deletes an SLI resource.",
