  "definitions": {
    "AmwAccount": {
      "type": "object",
      "description": "Represents an Azure Monitor Workspace (AMW) account used for emitting metrics.",
      "properties": {
        "resourceId": {
          "type": "string",
          "format": "arm-id",
          "description": "The ARM resource ID of the account where metrics are emitted."
        },
        "identity": {
          "type": "string",
          "format": "arm-id",
          "description": "The ARM resource ID of the managed identity with access to the source account."
        }
      },
      "required": [
        "resourceId",
        "identity"
      ]
    },
    "Azure.ResourceManager.ResourceProvisioningState": {
      "type": "string",
      "description": "The provisioning state of a resource type.",
      "enum": [
        "Succeeded",
        "Failed",
        "Canceled"
      ],
      "x-ms-enum": {
        "name": "ResourceProvisioningState",
        "modelAsString": true,
        "values": [
          {
            "name": "Succeeded",
            "value": "Succeeded",
            "description": "Resource has been created."
          },
          {
            "name": "Failed",
            "value": "Failed",
            "description": "Resource creation failed."
          },
          {
            "name": "Canceled",
            "value": "Canceled",
            "description": "Resource creation was canceled."
          }
        ]
      },
      "readOnly": true
    },
    "Baseline": {
      "type": "object",
      "description": "Defines the target parameters for a Slo baseline.",
      "properties": {
        "value": {
          "type": "number",
          "format": "float",
          "description": "The user-defined or Azure-defined target value used for comparison against the SLI value.",
          "minimum": 0,
          "maximum": 100
        },
        "evaluationPeriodDays": {
          "type": "integer",
          "format": "int32",
          "description": "The time frame (in days) used for SLI evaluation.",
          "minimum": 1,
          "maximum": 90
        },
        "evaluationCalculationType": {
          "$ref": "#/definitions/EvaluationCalculationType",
          "description": "Specifies how evaluation is calculated, either based on calendar days or a rolling window."
        }
      },
      "required": [
        "value",
        "evaluationPeriodDays",
        "evaluationCalculationType"
      ]
    },
    "BaselineProperties": {
      "type": "object",
      "description": "Defines the properties of a baseline.",
      "properties": {
        "baseline": {
          "$ref": "#/definitions/Baseline",
          "description": "Defines the baseline target, which is compared against the SLI value to determine compliance."
        }
      },
      "required": [
        "baseline"
      ]
    },
    "Category": {
      "type": "string",
      "description": "Defines the category of an SLI",
      "enum": [
        "Availability",
        "Latency"
      ],
      "x-ms-enum": {
        "name": "Category",
        "modelAsString": true,
        "values": [
          {
            "name": "Availability",
            "value": "Availability",
            "description": "Indicates availability-related metrics."
          },
          {
            "name": "Latency",
            "value": "Latency",
            "description": "Indicates latency-related metrics."
          }
        ]
      }
    },
    "Condition": {
      "type": "object",
      "description": "Represents a filtering condition.",
      "properties": {
        "dimensionName": {
          "type": "string",
          "description": "Dimension name used in filtering."
        },
        "scalarFunction": {
          "$ref": "#/definitions/ScalarFunction",
          "description": "Scalar function applied for filtering."
        },
        "samplingType": {
          "$ref": "#/definitions/SamplingType",
          "description": "Defines the sampling type."
        },
        "operator": {
          "$ref": "#/definitions/ConditionOperator",
          "description": "Operator used in the filtering condition."
        },
        "value": {
          "type": "string",
          "description": "Value used in filtering. For most operators (eq, ne, lt, lte, gt, gte, startswith, notstartswith, contains, notcontains) this is a single value (for example \"GetContosoUsers\"). For the `in` and `notin` operators, multiple values must be joined by the delimiter `^^` (for example \"east^^west^^north\")."
        }
      },
      "required": [
        "operator",
        "value"
      ]
    },
    "ConditionOperator": {
      "type": "string",
      "description": "Defines operators used in filter conditions.",
      "enum": [
        "eq",
        "ne",
        "lt",
        "lte",
        "gt",
        "gte",
        "in",
        "notin",
        "startswith",
        "notstartswith",
        "contains",
        "notcontains"
      ],
      "x-ms-enum": {
        "name": "ConditionOperator",
        "modelAsString": true,
        "values": [
          {
            "name": "Equal",
            "value": "eq",
            "description": "Equal to."
          },
          {
            "name": "NotEqual",
            "value": "ne",
            "description": "Not equal to."
          },
          {
            "name": "LessThan",
            "value": "lt",
            "description": "Less than."
          },
          {
            "name": "LessThanOrEqual",
            "value": "lte",
            "description": "Less than or equal to."
          },
          {
            "name": "GreaterThan",
            "value": "gt",
            "description": "Greater than."
          },
          {
            "name": "GreaterThanOrEqual",
            "value": "gte",
            "description": "Greater than or equal to."
          },
          {
            "name": "In",
            "value": "in",
            "description": "Matches when `value` is one of the items in the `^^`-delimited list (for example, `value` = \"east^^west^^north\")."
          },
          {
            "name": "NotIn",
            "value": "notin",
            "description": "Matches when `value` is none of the items in the `^^`-delimited list (for example, `value` = \"east^^west^^north\")."
          },
          {
            "name": "StartsWith",
            "value": "startswith",
            "description": "Starts with."
          },
          {
            "name": "NotStartsWith",
            "value": "notstartswith",
            "description": "Does not start with."
          },
          {
            "name": "Contains",
            "value": "contains",
            "description": "Contains the value."
          },
          {
            "name": "NotContains",
            "value": "notcontains",
            "description": "Does not contain the value."
          }
        ]
      }
    },
    "EvaluationCalculationType": {
      "type": "string",
      "description": "Specifies the method for evaluation calculation.",
      "enum": [
        "CalendarDays",
        "RollingDays"
      ],
      "x-ms-enum": {
        "name": "EvaluationCalculationType",
        "modelAsString": true,
        "values": [
          {
            "name": "CalendarDays",
            "value": "CalendarDays",
            "description": "Calculates evaluation based on a fixed calendar period."
          },
          {
            "name": "RollingDays",
            "value": "RollingDays",
            "description": "Calculates evaluation using a rolling time window."
          }
        ]
      }
    },
    "EvaluationType": {
      "type": "string",
      "description": "Specifies how the SLI is evaluated.",
      "enum": [
        "WindowBased",
        "RequestBased"
      ],
      "x-ms-enum": {
        "name": "EvaluationType",
        "modelAsString": true,
        "values": [
          {
            "name": "WindowBased",
            "value": "WindowBased",
            "description": "Evaluates SLI based on time windows."
          },
          {
            "name": "RequestBased",
            "value": "RequestBased",
            "description": "Evaluates SLI based on request counts."
          }
        ]
      }
    },
    "ExecutionMessage": {
      "type": "object",
      "description": "Represents a KQL-M query execution message.",
      "properties": {
        "severity": {
          "$ref": "#/definitions/MessageSeverity",
          "description": "The message severity."
        },
        "text": {
          "type": "string",
          "description": "The message text."
        },
        "documentationLink": {
          "type": "string",
          "format": "uri",
          "description": "The message documentation link."
        },
        "statementContext": {
          "$ref": "#/definitions/StatementContextInformation",
          "description": "The message statement context."
        }
      },
      "required": [
        "severity",
        "text",
        "documentationLink",
        "statementContext"
      ]
    },
    "ExecutionState": {
      "type": "object",
      "description": "Represents the current execution state of an SLI.",
      "properties": {
        "state": {
          "type": "string",
          "description": "The execution state value."
        },
        "message": {
          "type": "string",
          "description": "A descriptive message related to the execution state."
        }
      },
      "required": [
        "state"
      ]
    },
    "HmsDuration": {
      "type": "string",
      "description": "Duration in HH:MM:SS format (e.g. 00:01:00) to match service response.",
      "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}$"
    },
    "KqlmQueryResult": {
      "type": "object",
      "description": "Represents the result of a KQL-M query.",
      "properties": {
        "requestId": {
          "type": "string",
          "description": "The request ID."
        },
        "state": {
          "$ref": "#/definitions/QueryState",
          "description": "The query state."
        },
        "timeSeriesSets": {
          "type": "array",
          "description": "The list of time series sets, where each set represents results for a query statement.",
          "items": {
            "$ref": "#/definitions/TimeSeriesSet"
          },
          "x-ms-identifiers": []
        },
        "executionMessages": {
          "type": "array",
          "description": "The list of KQL-M query execution messages.",
          "items": {
            "$ref": "#/definitions/ExecutionMessage"
          },
          "x-ms-identifiers": []
        }
      },
      "required": [
        "state",
        "timeSeriesSets",
        "executionMessages"
      ]
    },
    "MessageSeverity": {
      "type": "string",
      "description": "Represents the severity of a message.",
      "enum": [
        "Error",
        "Warning",
        "Info"
      ],
      "x-ms-enum": {
        "name": "MessageSeverity",
        "modelAsString": true,
        "values": [
          {
            "name": "Error",
            "value": "Error",
            "description": "Error message."
          },
          {
            "name": "Warning",
            "value": "Warning",
            "description": "Warning message."
          },
          {
            "name": "Info",
            "value": "Info",
            "description": "Informational message."
          }
        ]
      }
    },
    "Metric": {
      "type": "object",
      "description": "Defines a metric in the destination AMW account.",
      "properties": {
        "metricNamespace": {
          "type": "string",
          "description": "The namespace of the metric."
        },
        "metricName": {
          "type": "string",
          "description": "The name of the metric."
        }
      },
      "required": [
        "metricNamespace",
        "metricName"
      ]
    },
    "PreviewType": {
      "type": "string",
      "description": "Defines the available preview types for signal preview.",
      "enum": [
        "GoodSignal",
        "TotalSignal",
        "Signal",
        "Slo"
      ],
      "x-ms-enum": {
        "name": "PreviewType",
        "modelAsString": true,
        "values": [
          {
            "name": "GoodSignal",
            "value": "GoodSignal",
            "description": "Preview for good signal."
          },
          {
            "name": "TotalSignal",
            "value": "TotalSignal",
            "description": "Preview for total signal."
          },
          {
            "name": "Signal",
            "value": "Signal",
            "description": "Preview for signal."
          },
          {
            "name": "Slo",
            "value": "Slo",
            "description": "Preview for SLO evaluation."
          }
        ]
      }
    },
    "ProvisioningState": {
      "$ref": "#/definitions/Azure.ResourceManager.ResourceProvisioningState",
      "x-nullable": false
    },
    "QueryState": {
      "type": "string",
      "description": "Represents the state of a KQL-M query.",
      "enum": [
        "Success",
        "Failed"
      ],
      "x-ms-enum": {
        "name": "QueryState",
        "modelAsString": true,
        "values": [
          {
            "name": "Success",
            "value": "Success",
            "description": "Query succeeded."
          },
          {
            "name": "Failed",
            "value": "Failed",
            "description": "Query failed."
          }
        ]
      }
    },
    "ResultsMetadata": {
      "type": "object",
      "description": "Represents metadata for a KQL-M query result.",
      "properties": {
        "startTimeUtc": {
          "type": "string",
          "format": "date-time",
          "description": "The start time for the KQL-M query result."
        },
        "endTimeUtc": {
          "type": "string",
          "format": "date-time",
          "description": "The end time for the KQL-M query result."
        },
        "dataResolution": {
          "$ref": "#/definitions/HmsDuration",
          "description": "The data resolution of the KQL-M query result in HH:MM:SS format."
        },
        "resultantDimensions": {
          "type": "array",
          "description": "The list of output dimensions of the KQL-M query result.",
          "items": {
            "type": "string"
          }
        },
        "resultantSamplingTypes": {
          "type": "array",
          "description": "The list of output sampling types of the KQL-M query result.",
          "items": {
            "$ref": "#/definitions/SamplingTypeProjection"
          }
        },
        "datapointsCount": {
          "type": "integer",
          "format": "int64",
          "description": "The number of datapoints in the KQL-M query result."
        }
      },
      "required": [
        "startTimeUtc",
        "endTimeUtc",
        "dataResolution",
        "resultantDimensions",
        "resultantSamplingTypes",
        "datapointsCount"
      ]
    },
    "SamplingType": {
      "type": "string",
      "description": "Defines the available sampling types.",
      "enum": [
        "Average",
        "Sum",
        "Count",
        "Min",
        "Max"
      ],
      "x-ms-enum": {
        "name": "SamplingType",
        "modelAsString": true,
        "values": [
          {
            "name": "Average",
            "value": "Average",
            "description": "Average value."
          },
          {
            "name": "Sum",
            "value": "Sum",
            "description": "Summation."
          },
          {
            "name": "Count",
            "value": "Count",
            "description": "Count of occurrences."
          },
          {
            "name": "Min",
            "value": "Min",
            "description": "Minimum value."
          },
          {
            "name": "Max",
            "value": "Max",
            "description": "Maximum value."
          }
        ]
      }
    },
    "SamplingTypeProjection": {
      "type": "string",
      "description": "Represents sampling types used in SLI calculations.",
      "enum": [
        "Value",
        "Good",
        "Total",
        "Uptime",
        "Downtime",
        "Burnrate"
      ],
      "x-ms-enum": {
        "name": "SamplingTypeProjection",
        "modelAsString": true,
        "values": [
          {
            "name": "Value",
            "value": "Value",
            "description": "The calculated SLI value."
          },
          {
            "name": "Good",
            "value": "Good",
            "description": "Count of good requests or events."
          },
          {
            "name": "Total",
            "value": "Total",
            "description": "Total count of requests or events."
          },
          {
            "name": "Uptime",
            "value": "Uptime",
            "description": "Uptime measurement."
          },
          {
            "name": "Downtime",
            "value": "Downtime",
            "description": "Downtime measurement."
          },
          {
            "name": "Burnrate",
            "value": "Burnrate",
            "description": "Error budget burn rate."
          }
        ]
      }
    },
    "SamplingTypesDataDictionary": {
      "type": "object",
      "description": "Dictionary of sampling types to metric values.",
      "properties": {
        "Burnrate": {
          "type": "array",
          "description": "Error budget burn rate values.",
          "items": {
            "type": "number",
            "format": "double"
          }
        },
        "Good": {
          "type": "array",
          "description": "Count of good requests or events values.",
          "items": {
            "type": "number",
            "format": "double"
          }
        },
        "Total": {
          "type": "array",
          "description": "Total count of requests or events values.",
          "items": {
            "type": "number",
            "format": "double"
          }
        },
        "Value": {
          "type": "array",
          "description": "The calculated SLI value.",
          "items": {
            "type": "number",
            "format": "double"
          }
        },
        "Uptime": {
